SET statement_timeout='60s';
\copy (WITH latest AS (SELECT DISTINCT ON (f.stock_id) f.stock_id, f.shares_outstanding, f.share_basis_status FROM financial_statement f JOIN stock s ON s.id=f.stock_id WHERE s.market_code='US' AND s.is_active AND f.published_at <= DATE '2026-10-02' AND f.shares_outstanding IS NOT NULL AND f.shares_outstanding>0 AND f.period_end >= DATE '2024-10-02' ORDER BY f.stock_id, f.period_end DESC, f.published_at DESC, f.revision_no DESC) SELECT s.ticker, s.sic_code, l.shares_outstanding, coalesce(l.share_basis_status,'') , (SELECT max(trade_date) FROM price_daily p WHERE p.stock_id=s.id) last_px, s.listing_exchange, left(s.name,60) FROM latest l JOIN stock s ON s.id=l.stock_id WHERE l.share_basis_status IS DISTINCT FROM 'UNRESOLVED' ORDER BY 1) TO 'pool.tsv'
